<?php requireAdmin(); $items=db()->query('SELECT mi.*, p.title parent_title FROM menu_items mi LEFT JOIN menu_items p ON p.id=mi.parent_id ORDER BY COALESCE(mi.parent_id,mi.id), mi.sort_order')->fetchAll(); $parents=array_filter($items,fn($i)=>$i['parent_id']===null); $mods=db()->query('SELECT module_key,title FROM modules WHERE is_active=1 ORDER BY title')->fetchAll(); ?>
<div class="panel"><h2>Menüverwaltung</h2><form class="ajax-form form-grid" action="ajax/admin_menu.php" data-reload="admin_menu" method="post"><?= csrfField() ?><input type="hidden" name="id" value="0"><label>Titel<input name="title" required></label><label>Übergeordneter Punkt<select name="parent_id"><option value="0">Hauptpunkt</option><?php foreach($parents as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['title']) ?></option><?php endforeach; ?></select></label><label>Modul-Key<select name="module_key"><option value="">kein Modul</option><?php foreach($mods as $m): ?><option value="<?= e($m['module_key']) ?>"><?= e($m['module_key']) ?> - <?= e($m['title']) ?></option><?php endforeach; ?></select></label><label>Sortierung<input type="number" name="sort_order" value="100"></label><label>Icon<input name="icon"></label><label><input type="checkbox" name="is_active" checked> aktiv</label><label><input type="checkbox" name="admin_only"> nur Admin</label><div><button>Menüpunkt anlegen</button></div></form></div>
<div class="panel"><table class="data-table js-data-table"><thead><tr><th>ID</th><th>Parent</th><th>Titel</th><th>Modul</th><th>Sort.</th><th>Status</th><th>Admin</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= (int)$i['id'] ?></td><td><?= e($i['parent_title'] ?: '-') ?></td><td><?= e($i['title']) ?></td><td><?= e($i['module_key'] ?: '-') ?></td><td><?= (int)$i['sort_order'] ?></td><td><?= statusBadge((int)$i['is_active']?'aktiv':'inaktiv') ?></td><td><?= (int)$i['admin_only']?'ja':'nein' ?></td></tr><?php endforeach; ?></tbody></table></div><script>initDataTable('.js-data-table');</script>
